using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using UnityEngine;using UnityEditor;
public static class ClimateBalanceTests {
static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static T Get<T>(object o,string n)=>(T)o.GetType().GetField(n,F).GetValue(o);
[MenuItem("Tools/HoneyComb/검증/Run Climate Balance Tests")] public static void Run(){try{string dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../outputs/climate-balance"));Directory.CreateDirectory(dir);File.WriteAllText(dir+"/integration.csv","tick,model,massErrorKg,energyErrorJ,minTemperature,maxTemperature\n");var w=new GameWorld(WeatherAssetLoader.Create(42));w.PrepareThermal(ThermalMaterials.Load());w.Thermal.CalculateMinuteAsync(w.Weather.Minute+1,CancellationToken.None).GetAwaiter().GetResult();var domain=Get<object>(w.Thermal,"climate");var models=Get<HiveClimate.Model[]>(domain,"models");for(int tick=0;tick<120;tick++){for(int j=0;j<models.Length;j++){var m=models[j];var before=m.Audit();typeof(HiveClimate.Model).GetMethod("LiveMinute",F).Invoke(m,new object[]{5d,.55,1d});var after=m.Audit();double me=after.m-before.m-m.ExternalWaterKg,ee=after.e-before.e-m.ExternalSensibleEnergyJ-m.ExternalMoistureEnergyJ;var t=Get<double[]>(m,"temperature");if(Math.Abs(me)>1e-9||Math.Abs(ee)>1e-5)throw new Exception("Budget "+me+" "+ee);if(tick%30==0)File.AppendAllText(dir+"/integration.csv",$"{tick},{j},{me:R},{ee:R},{t.Min():R},{t.Max():R}\n");}if(tick%30==0)Debug.Log("BALANCE tick="+tick);}var snap=new WorldSaveSnapshot{World=w,UtcTicks=638000000000000000,TargetMinute=w.CurrentGameMinute};var bytes=WorldSaveCodec.Encode(snap);var loaded=WorldSaveCodec.Decode(bytes);loaded.World.PrepareThermal(ThermalMaterials.Load());loaded.World.Thermal.PrepareExchange();loaded.World.Thermal.Dispose();w.Thermal.Dispose();PyramidThermalTests.Analytic(ThermalMaterials.Load());PyramidThermalTests.Exterior(ThermalMaterials.Load());PyramidThermalTests.Local(ThermalMaterials.Load());PyramidThermalTests.Live();var live=new GameWorld(WeatherAssetLoader.Create(42));live.PrepareThermal(ThermalMaterials.Load());live.BeeCycle.SeedDemo();var scheduler=GameTimeRuntime.CreateWorldScheduler(live);scheduler.RunToAsync(live.CurrentGameMinute+1440,()=>System.Threading.Tasks.Task.CompletedTask,()=>System.Threading.Tasks.Task.CompletedTask,CancellationToken.None).GetAwaiter().GetResult();live.Thermal.Dispose();Debug.Log("BALANCE INTEGRATION PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
